import{_ as o,C as a,o as s,c as l,E as t,a2 as n}from"./chunks/framework.DyLyN3RJ.js";const b=JSON.parse('{"title":"更像需求，不一定更能满足任务","description":"","frontmatter":{"article_type":"research-note","edition":"research-center","language":"zh","title":"更像需求，不一定更能满足任务","summary":"明确选择的二维公式反例显示，增加无关能力或放宽需求可以降低相似度，而需求满足分数不变。内部演示还区分分数稳定、选择稳定与可行性；它们不构成原研究复现，也未验证实际任务收益。","research_question":"对于明确给出的适配公式，无关能力增加或需求放宽能否降低相似度分数，而需求满足分数保持不变？","research_question_en":"For explicitly defined suitability formulas, can irrelevant added capability or relaxed requirements lower similarity while requirement satisfaction stays unchanged?","date":"2026-11-10","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261110-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-10-sig-20261110-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-11-10-sig-20261110-006.md","filePath":"zh/industry/2026-11-10-sig-20261110-006.md","lastUpdated":1794325439000}'),c={name:"zh/industry/2026-11-10-sig-20261110-006.md"};function d(p,e,h,u,_,m){const r=a("ArticleCover"),i=a("ArticleTableScroll");return s(),l("div",null,[t(r,{image:"/assets/covers/daily-2026-11-10-sig-20261110-006-cover.png",kicker:"研究成果",title:"更像需求，不一定更能满足任务",summary:"明确选择的二维公式反例显示，增加无关能力或放宽需求可以降低相似度，而需求满足分数不变。内部演示还区分分数稳定、选择稳定与可行性；它们不构成原研究复现，也未验证实际任务收益。",version:"2026-11-10",languageHref:"/en/industry/2026-11-10-sig-20261110-006",languageLabel:"English"}),t(i,{language:"zh"}),e[0]||(e[0]=n('<h1 id="更像需求-不一定更能满足任务" tabindex="-1">更像需求，不一定更能满足任务 <a class="header-anchor" href="#更像需求-不一定更能满足任务" aria-label="Permalink to &quot;更像需求，不一定更能满足任务&quot;">​</a></h1><p>候选者多了一项任务用不到的能力，评分反而下降了。这不一定是计算错误：相似度衡量的是形状接近，需求满足关心的是够不够用。下面用一组可检查的二维例子说明差别，并指出为什么挑选候选者还要检查可行性和平局，而不能只比较分数是否稳定。</p><h2 id="四种公式回答两类问题" tabindex="-1">四种公式回答两类问题 <a class="header-anchor" href="#四种公式回答两类问题" aria-label="Permalink to &quot;四种公式回答两类问题&quot;">​</a></h2><p>设能力向量为 a，需求为 b，各维度均为无量纲数。本文内部演示明确选择四种公式，而不是重建原研究实现：余弦取夹角相似度；倒数欧氏分数取 1/(1+距离)；覆盖率取正需求维度中已满足的比例；短缺分数取 1−总正短缺/总需求。这里只处理总需求为正的例子。<a href="/joinwell52/assets/evidence/2026-11-10-sig-20261110-006/suitability-probe.json">公式、输入与结果</a></p><p>前两种比较整个向量的接近程度。后两种只追问需求缺口，超过需求的能力不会因此受罚。没有脱离目标的“正确分数”：要寻找外形或配置相似者，相似度很合理；要判断是否够用，就必须解释为什么多余能力应改变结果。若额外能力带来能耗或成本，它也不再是本例所假设的无关维度。</p><h2 id="一个能力增加、相似度下降的反例" tabindex="-1">一个能力增加、相似度下降的反例 <a class="header-anchor" href="#一个能力增加、相似度下降的反例" aria-label="Permalink to &quot;一个能力增加、相似度下降的反例&quot;">​</a></h2><p>需求保持为 (1,0)，能力从 (1,0) 增至 (1,1)。内部实验结果中，余弦分数从 1 降至约 0.707，倒数欧氏分数从 1 降至 0.5；覆盖率和短缺分数都保持 1。候选者仍完全满足第一维需求，却因为向量更不像需求而失分。</p><p>另一组保持能力 (1,1)，把需求从 (1,1) 放宽为 (1,0.5)。余弦分数从约 1 降至约 0.949，倒数欧氏分数从 1 降至约 0.667，两种需求满足分数仍为 1。补足所需能力的正向对照则使四种分数都改善；完全不变的输入也保持分数不变。这些对照避免把所有变化都误写成相似度的缺点。</p><p>这些是同日分析阶段已执行的确定性数学反例，没有随机种子、真实机器人或模型调用。它们说明所列公式存在这种行为，不说明行为在实际任务中有多常见。</p><h2 id="分数稳定-首选仍可能改变" tabindex="-1">分数稳定，首选仍可能改变 <a class="header-anchor" href="#分数稳定-首选仍可能改变" aria-label="Permalink to &quot;分数稳定，首选仍可能改变&quot;">​</a></h2><p>另一个内部构造把两个分数从 (0.5001,0.5) 改为 (0.5,0.5001)。每项只变动 0.0001，首选却互换了。因此分数变化幅度小，不足以说明决策稳定。读者应同时看首选差距、平局规则，以及扰动后选择是否改变。</p><p>全零输入也会暴露含义差异：按固定规则取最大值仍可返回第一个索引。若这里的零明确定义为不可行，就没有可行候选；返回索引只是算法完成，不是任务有人能做。这个解释依赖零值语义，不能推广到所有打分系统。</p><p>我们的判断是，先声明硬约束和不可行状态，再解释排序目标，比把所有差别压进一个数字更便于审查。覆盖率不能区分超额能力的价值，硬筛选也可能排空候选集合；通过这些性质测试仍不能证明任务完成得更好。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的外部背景是<a href="https://arxiv.org/html/2610.27504v1" target="_blank" rel="noreferrer">机器人与任务适配研究第一版</a>第二、四节。论文比较需求导向和相似度导向方法，并讨论评分与选择的稳定性；它没有测量任务执行真值。作者具体归一化、代码、生成种子和完整计数不在已核验材料中。</p><p>论文中的违规频率和模型结果属于来源陈述；本页的数值属于内部实验，二者不是独立复现关系。上述公式、四组向量对照和两组选择演示均保存在随文结果中，来源哈希保留在实验附件。本文没有运行语言模型，也没有复现作者报告的 98.55% 频率。公开发表或被引用不能替代这类复现。</p><p>文献题录：<a href="https://arxiv.org/html/2610.27504v1" target="_blank" rel="noreferrer">《异构多机器人任务分配中的机器人与任务适配》</a>（原题：Robot–Task Suitability in Heterogeneous Multi-Robot Task Allocation；作者：Daniel Weiner、Raj Korpan；机构：纽约市立大学研究生中心及亨特学院）。预印本第一版，2026 年 10 月 20 日；它是问题与方法比较的来源，不是本文公式的实现证明或任务执行验证。</p><h2 id="把分数用于选人之前-还缺哪些验证" tabindex="-1">把分数用于选人之前，还缺哪些验证 <a class="header-anchor" href="#把分数用于选人之前-还缺哪些验证" aria-label="Permalink to &quot;把分数用于选人之前，还缺哪些验证&quot;">​</a></h2><p>这组二维构造不包含争用、联合能力、任务排程或耦合约束，也没有比较实际完成率、安全或调度收益。从机器人适配迁移到软件智能体，仍是待验证假设。</p><p>实际采用前，可先写明每一维的单位、归一化、是否允许能力过剩、硬约束和弃选条件，再用真实结果检验排序是否有用。对差距很小的候选，是否需要追加信息或弃选，应成为显式决策问题。本文提供的是能审查评分含义的最小例子，尚不能据此选出一种最佳分配器。</p>',20))])}const f=o(c,[["render",d]]);export{b as __pageData,f as default};
